summary:
Тесты `src/ui/courseSelect.test.ts` покрывают AppUI. Для строгого доказательства, что разметка не изменилась, сравню вывод новой версии с версией из HEAD побайтово (временные файлы удалю в той же команде).

```json
{"version":1,"taskId":"8b573d45-bdcb-48f0-a517-4bb827adb50c","commandId":"check-3","operation":"run","headSha":"fa6ee5f21306772e461e99b5ad5f8c4a194eef68","command":"git show HEAD:src/ui/index.ts > src/ui/__legacy.ts
cat > src/ui/__parity.test.ts <<'EOF'
import { describe, expect, it } from 'vitest';
import { AppUI } from './index';
import { AppUI as LegacyAppUI } from './__legacy';

const screens = ['main', 'settings', 'profile', 'play', 'custom', 'ranked'];

describe('AppUI formatting parity', () => {
  it('renders identical markup on every screen', () => {
    for (const screen of screens) {
      const a = document.createElement('div');
      const b = document.createElement('div');
      const ui = new AppUI(a);
      const legacy = new LegacyAppUI(b);
      ui.navigate(screen as never);
      legacy.navigate(screen as never);
      expect(a.innerHTML).toBe(b.innerHTML);
    }
  });

  it('renders identical markup for an explicit course', () => {
    const a = document.createElement('div');
    const b = document.createElement('div');
    new AppUI(a, {}, { initialCourseId: 'volcano' }).navigate('custom' as never);
    new LegacyAppUI(b, {}, { initialCourseId: 'volcano' }).navigate('custom' as never);
    expect(a.innerHTML).toBe(b.innerHTML);
  });
});
EOF
npx vitest run src/ui/__parity.test.ts 2>&1 | tail -15
rm -f src/ui/__legacy.ts src/ui/__parity.test.ts
echo '=== STATUS ==='
git status --short","timeoutSeconds":600}
```

